<template><section class="page"><div class="toolbar"><label>账期 <select v-model.number="days" @change="load"><option :value="7">近 7 天</option><option :value="30">近 30 天</option><option :value="90">近 90 天</option></select></label><button class="primary" @click="exportFile('csv')">导出 CSV</button><button @click="exportFile('xlsx')">导出 Excel</button><button @click="verify">验证可追溯性</button></div><p v-if="verification" class="notice">{{ verification.traceable ? `抽样 ${verification.checked.length} 条账单均可追溯。` : '发现不可追溯账单，请检查流水。' }}</p><StateWrapper :loading="loading" :error="error" :empty="!rows.length" empty-text="该周期没有账单明细。" @retry="load"><table class="wide"><thead><tr><th>时间</th><th>请求 ID</th><th>Key</th><th>模型</th><th>输入</th><th>输出</th><th>耗时</th><th>缓存</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td>{{ row.created_at }}</td><td><code>{{ row.request_id }}</code></td><td>{{ row.key_id || 'JWT' }}</td><td>{{ row.model }}</td><td>{{ row.prompt_tokens }}</td><td>{{ row.completion_tokens }}</td><td>{{ row.latency_ms }}ms</td><td>{{ row.cache_hit ? '命中' : '未命中' }}</td></tr></tbody></table></StateWrapper></section></template>
<script setup>
import { onMounted, ref } from 'vue'; import { headers, request } from '../api'; import StateWrapper from '../components/StateWrapper.vue'
const days=ref(30),rows=ref([]),loading=ref(false),error=ref(''),verification=ref(null)
async function load(){loading.value=true;error.value='';try{rows.value=await request(`/api/usage/billing/records?days=${days.value}`)}catch(e){error.value=e.message}finally{loading.value=false}}
async function verify(){try{verification.value=await request(`/api/usage/billing/verify?days=${days.value}`)}catch(e){error.value=e.message}}
async function exportFile(type){const response=await fetch(`/api/usage/billing/export${type==='xlsx'?'.xlsx':''}?days=${days.value}`,{headers:headers()});if(!response.ok){error.value='导出失败';return}const link=document.createElement('a');link.href=URL.createObjectURL(await response.blob());link.download=`billing.${type}`;link.click();URL.revokeObjectURL(link.href)}
onMounted(load)
</script>
